question.solution:
SHARED = {'代码段', '数据段', '堆', '打开的文件', '当前工作目录', '进程PID', '信号处理函数'}
PRIVATE = {'程序计数器', '寄存器组', '线程栈', '线程ID', '线程局部存储', 'errno'}

def classify_thread_items(items):
    shared = []
    private = []
    unknown = []
    for name in items:
        if name in SHARED:
            shared.append(name)
        elif name in PRIVATE:
            private.append(name)
        else:
            unknown.append(name)
    return shared, private, unknown

print(classify_thread_items(['代码段', '线程栈', '堆', '线程ID']))
print(classify_thread_items(['数据段', '数据段', '寄存器组', '神奇资源']))
print(classify_thread_items([]))
